int64_t IPSEC_CFG_PP6AndPP4PIDDelete(int64_t context_base, const IpsecPidMessage *message)
{
    IpsecContext *context = (IpsecContext *)context_base;
    int component_type;

    if (context_base == 0 || message == NULL) {
        VRP_Assert(IPSEC_CFG_CLASS_C, 895, 0);
        return 1;
    }

    component_type = (int)message->component_type;
    if (component_type != 114 && component_type != 102)
        return 0;

    if (component_type == 114) {
        IPSEC_CFG_LOG_IF_ENABLED(context, 907, "Deleting PP6 PID 0x%x", message->pid);
        if (context->pp6_pid != message->pid)
            return 0;
        IPSEC_MGTI_HAUnSubscribePP6(context_base);
        IPSEC_SOCKI_UpdatePP6Status(message->pid, 1, context_base);
        return 0;
    }

    IPSEC_CFG_LOG_IF_ENABLED(context, 917, "Deleting PP4 PID 0x%x", message->pid);
    if (context->pp4_pid != message->pid)
        return 0;
    IPSEC_MGTI_HAUnSubscribePP4(context_base);
    IPSEC_SOCKI_UpdatePP4Status(message->pid, 1, context_base);
    return 0;
}

