#define IPSEC_SSP_COOKIE  3561718379ULL

#define STACK_GUARD_INIT() uintptr_t stack_cookie = _stack_chk_guard
#define STACK_GUARD_CHECK()            \
    do {                              \
        if (stack_cookie != _stack_chk_guard) \
            __stack_chk_fail();       \
    } while (0)

#define RAW_U8(base, off)  (*(uint8_t *)((uint8_t *)(base) + (off)))
#define RAW_U16(base, off) (*(uint16_t *)((uint8_t *)(base) + (off)))
#define RAW_I16(base, off) (*(int16_t *)((uint8_t *)(base) + (off)))
#define RAW_U32(base, off) (*(uint32_t *)((uint8_t *)(base) + (off)))
#define RAW_U64(base, off) (*(uint64_t *)((uint8_t *)(base) + (off)))
#define RAW_PTR(type, base, off) ((type *)((uint8_t *)(base) + (off)))

#define IPSEC_CFG_LOG_WITH_CODE(ctx_ptr, code16, line_no, fmt, ...)                        \
    do {                                                                                    \
        IPSEC_MakeDbgCompStrSetter((int64_t)(ctx_ptr), 0, (line_no), (fmt), ##__VA_ARGS__); \
        if (g_ucIpsecDebugEnv)                                                              \
            IPSEC_Print_File((int64_t)(ctx_ptr), 1, (ctx_ptr)->debug_text);                \
        SSP_Debug(                                                                          \
            (ctx_ptr)->debug_id,                                                            \
            ((uint32_t)(uint16_t)(code16)) | 0x9990000u,                                   \
            (ctx_ptr)->ssp_handle,                                                          \
            IPSEC_SSP_COOKIE,                                                               \
            "%s",                                                                          \
            (ctx_ptr)->debug_text);                                                         \
    } while (0)

#define IPSEC_CFG_LOG_IF_ENABLED(ctx_ptr, line_no, fmt, ...)                            \
    do {                                                                                \
        if ((ctx_ptr)->debug_enabled_primary == 1)                                      \
            IPSEC_CFG_LOG_WITH_CODE((ctx_ptr), -25344, (line_no), (fmt), ##__VA_ARGS__); \
        else if ((ctx_ptr)->debug_enabled_secondary == 1)                               \
            IPSEC_CFG_LOG_WITH_CODE((ctx_ptr), -28416, (line_no), (fmt), ##__VA_ARGS__); \
    } while (0)

