/*
 * Address: 0x12778
 * Symbol: IPSEC_CFG_VRCreate
 * Purpose: Add a VR when it does not already exist, and emit debug logs for the outcome.
 * Security notes: None.
 */
int64_t IPSEC_CFG_VRCreate(int64_t context_base, unsigned int *vr_id_ptr)
{
    bool invalid;
    int64_t result;
    unsigned int add_status;
    IpsecContext *context = (IpsecContext *)context_base;

    if (context_base != 0)
        invalid = (vr_id_ptr == NULL);
    else
        invalid = true;

    if (invalid) {
        VRP_Assert(IPSEC_CFG_CLASS_C, 1164, 0);
        return 1;
    }

    if (VOS_AVL3_Find(context_base + 276, vr_id_ptr, context_base + 300) != 0)
        return 0;

    add_status = (unsigned int)IPSEC_MGTI_AddVR(*vr_id_ptr, context_base);
    if (add_status == 0) {
        IPSEC_CFG_LOG_IF_ENABLED(context, 1174, "Successfully added VS %d", *vr_id_ptr);
        return 0;
    }

    result = add_status;
    if (context->debug_enabled_primary == 1)
        IPSEC_CFG_LOG_WITH_CODE(context, -25344, 1176, "Failed to Add VS %d", *vr_id_ptr);
    else if (context->debug_enabled_secondary == 1)
        IPSEC_CFG_LOG_WITH_CODE(context, -28416, 1176, "Failed to Add VS %d", *vr_id_ptr);
    return result;
}

