/*
 * Address: 0x12A08
 * Symbol: IPSEC_CFG_DispStatsSetCondition
 * Purpose: Extract the VR id and stats selector from a display request.
 * Security notes: None.
 */
uint32_t *IPSEC_CFG_DispStatsSetCondition(uint32_t *condition_out, int64_t request_base)
{
    const IpsecDisplayRequest *request = (const IpsecDisplayRequest *)request_base;
    uint16_t index;
    uint64_t entry_offset;

    if (request->attribute_count == 0)
        return condition_out;

    index = 0;
    entry_offset = 0;
    do {
        const IpsecCfgAttrEntry *entry = (const IpsecCfgAttrEntry *)((uint8_t *)request->entries + entry_offset);
        int type;

        while (1) {
            type = entry->type;
            if (type != 17)
                break;

            ++index;
            entry_offset += sizeof(IpsecCfgAttrEntry);
            condition_out[0] = *(const uint32_t *)entry->value;
            if (request->attribute_count <= index)
                return condition_out;
            entry = (const IpsecCfgAttrEntry *)((uint8_t *)request->entries + entry_offset);
        }

        if (type == 20)
            condition_out[1] = *(const uint32_t *)entry->value;

        ++index;
        entry_offset += sizeof(IpsecCfgAttrEntry);
    } while (request->attribute_count > index);

    return condition_out;
}

