/*
 * Address: 0x19610
 * Symbol: IPSEC_FESI_ProcMsg
 * Purpose: Dispatch incoming FES messages by message type and source interface.
 * Security notes: None.
 */
int64_t IPSEC_FESI_ProcMsg(int interface_id, int64_t message_base, int64_t context_base)
{
    unsigned int message_type;
    int secondary_log_enabled;
    IpsecContext *context = (IpsecContext *)context_base;

    if (context_base == 0) {
        VRP_Assert(IPSEC_FES_MAIN_C, 110, 0);
        message_type = RAW_U8((void *)message_base, 3);
        goto dispatch_without_log;
    }

    message_type = RAW_U8((void *)message_base, 3);
    if (context->debug_enabled_primary == 1) {
        IPSEC_CTX_LOG_WITH_CODE(context, 3, -25344, 110, "[IPSEC] Received FES Message Type: %d", message_type);
    } else if (context->debug_enabled_secondary == 1) {
        IPSEC_CTX_LOG_WITH_CODE(context, 3, -28416, 110, "[IPSEC] Received FES Message Type: %d", message_type);
    }

    message_type = RAW_U8((void *)message_base, 3);
    if (message_type == 18)
        goto handle_batch_begin_ack;

    if (message_type > 0x12) {
        if (message_type == 35)
            goto handle_service_notify;
        if (message_type > 0x23) {
            if (message_type - 41 <= 1)
                goto handle_verify_stop;
        } else {
            if (message_type == 19)
                goto handle_batch_end_ack;
            if (message_type == 22)
                goto handle_notify_seq_err;
        }
    } else {
        if (message_type == 3)
            goto handle_unsubscribe;
        if (message_type <= 3) {
            if (message_type == 2)
                goto handle_subscribe;
        } else {
            if (message_type == 14)
                goto handle_verify_request;
            if (message_type == 17)
                goto handle_smooth_request;
        }
    }

    if (context->debug_enabled_primary == 1) {
        IPSEC_MakeDbgCompStrSetter(context_base, 3, 160, "[IPSEC] Received Invalid FES message ");
        if (g_ucIpsecDebugEnv)
            IPSEC_Print_File(context_base, 1, (const char *)context_base + 424);
        SSP_Debug(
            RAW_U32((void *)context_base, 4),
            161062144,
            RAW_U64((void *)context_base, 416),
            IPSEC_SSP_COOKIE,
            "%s",
            (const char *)context_base + 424);
        return 0;
    }

    secondary_log_enabled = context->debug_enabled_secondary;
    if (secondary_log_enabled == 1) {
        IPSEC_MakeDbgCompStrSetter(context_base, 3, 160, "[IPSEC] Received Invalid FES message ");
        if (g_ucIpsecDebugEnv)
            IPSEC_Print_File(context_base, 1, (const char *)context_base + 424);
        SSP_Debug(
            RAW_U32((void *)context_base, 4),
            161059072,
            RAW_U64((void *)context_base, 416),
            IPSEC_SSP_COOKIE,
            "%s",
            (const char *)context_base + 424);
    }
    return 0;

handle_batch_begin_ack:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    IPSEC_FES_ProcBatchUpdateBeginAckMsg(message_base, context_base);
    return 0;

handle_notify_seq_err:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    IPSEC_FES_SendNotifySeqErrAckMsg(message_base, (unsigned int *)context_base);
    return 0;

handle_batch_end_ack:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    if ((int8_t)RAW_U8((void *)message_base, 2) < 0)
        IPSEC_FES_ProcBatchUpdateEndAckMsg(context_base);
    return 0;

handle_service_notify:
    IPSEC_FES_ServiceNotifyStateMsg(interface_id, (uint16_t *)message_base, context_base);
    return 0;

handle_unsubscribe:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    IPSEC_FES_ProcUnsubscribeMsg((uint16_t *)message_base, context_base);
    return 0;

handle_subscribe:
    IPSEC_FES_ProcSubscribeMsg(interface_id, (uint16_t *)message_base, context_base);
    return 0;

handle_verify_request:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    IPSEC_FES_ProcVerifyRequestMsg(message_base, context_base);
    return 0;

handle_smooth_request:
    if (RAW_U32((void *)context_base, 244) != (uint32_t)interface_id)
        return 1;
    IPSEC_FES_ProcSmoothRequestMsg((uint16_t *)message_base, context_base);
    return 0;

handle_verify_stop:
    IPSEC_FES_ProcVerifyStopRequestMsg(message_base, context_base);
    return 0;

dispatch_without_log:
    if (message_type == 18)
        goto handle_batch_begin_ack;
    if (message_type > 0x12) {
        if (message_type == 35)
            goto handle_service_notify;
        if (message_type > 0x23) {
            if (message_type - 41 <= 1)
                goto handle_verify_stop;
        } else {
            if (message_type == 19)
                goto handle_batch_end_ack;
            if (message_type == 22)
                goto handle_notify_seq_err;
        }
    } else {
        if (message_type == 3)
            goto handle_unsubscribe;
        if (message_type <= 3) {
            if (message_type == 2)
                goto handle_subscribe;
        } else {
            if (message_type == 14)
                goto handle_verify_request;
            if (message_type == 17)
                goto handle_smooth_request;
        }
    }
    VRP_Assert(IPSEC_FES_MAIN_C, 160, 0);
    return 0;
}

