/*
 * Address: 0x19B78
 * Symbol: IPSEC_HA_Fsm
 * Purpose: Execute one HA FSM transition, record history/diagnostics, log it, and dispatch the action.
 * Security notes: None.
 */
int64_t IPSEC_HA_Fsm(uint8_t event_id, int64_t context_base)
{
    unsigned int event_index = event_id;
    unsigned int current_state;
    unsigned int fsm_offset;
    uint8_t next_state;
    int action_id;
    const uint8_t *cell;
    IpsecContext *context = (IpsecContext *)context_base;

    if (context_base == 0)
        VRP_Assert(IPSEC_HA_FSM_C, 372, 0);

    current_state = RAW_U8((void *)context_base, 1152);
    fsm_offset = 12 * event_index + 2 * current_state;

    VOS_Util_DiagsStoreFSMHistory(
        g_astIpsecHaFsm[fsm_offset],
        g_astIpsecHaFsm[fsm_offset + 1],
        g_astIpsecHaFsm,
        event_index,
        (uint8_t *)context + 1152);
    VOS_Util_HitCell(0, &g_astIpsecHaFsm[12 * event_index + 2 * RAW_U8((void *)context_base, 1152)]);

    cell = &g_astIpsecHaFsm[12 * event_index + 2 * RAW_U8((void *)context_base, 1152)];
    next_state = cell[0];
    RAW_U8((void *)context_base, 1152) = next_state;
    action_id = cell[1];

    if (context->debug_enabled_primary == 1) {
        IPSEC_MakeDbgCompStrSetter(
            context_base,
            4,
            383,
            "HA FSM Current State = %s, Event = %s, Next State= %s Action = %d ",
            g_aszIPSEC_HA_FSMState[current_state],
            g_aszIPSEC_HA_FSMEvent[event_index],
            g_aszIPSEC_HA_FSMState[next_state],
            action_id);
        if (g_ucIpsecDebugEnv)
            IPSEC_Print_File(context_base, 1, (const char *)context_base + 424);
        SSP_Debug(
            RAW_U32((void *)context_base, 4),
            ((uint32_t)(uint16_t)-25344) | 0x9990000u,
            RAW_U64((void *)context_base, 416),
            IPSEC_SSP_COOKIE,
            "%s",
            (const char *)context_base + 424);
    } else if (context->debug_enabled_secondary == 1) {
        IPSEC_MakeDbgCompStrSetter(
            context_base,
            4,
            383,
            "HA FSM Current State = %s, Event = %s, Next State= %s Action = %d ",
            g_aszIPSEC_HA_FSMState[current_state],
            g_aszIPSEC_HA_FSMEvent[event_index],
            g_aszIPSEC_HA_FSMState[next_state],
            action_id);
        if (g_ucIpsecDebugEnv)
            IPSEC_Print_File(context_base, 1, (const char *)context_base + 424);
        SSP_Debug(
            RAW_U32((void *)context_base, 4),
            ((uint32_t)(uint16_t)-28416) | 0x9990000u,
            RAW_U64((void *)context_base, 416),
            IPSEC_SSP_COOKIE,
            "%s",
            (const char *)context_base + 424);
    }

    return g_apfIPSEC_HA_FSMAct[action_id](context_base + 1132, context_base);
}

/*
 * Address: 0x19D78
 * Symbol: IPSEC_HA_FsmActB
 * Purpose: Start the first batch-backup step or drive the FSM to event 3 when batch backup is disabled/queued.
 * Security notes: None.
 */
int64_t IPSEC_HA_FsmActB(int64_t a1, int64_t context_base)
{
    int64_t result;
    int64_t first_vr;
    IpsecContext *context = (IpsecContext *)context_base;

    (void)a1;

    if (RAW_U32((void *)context_base, 1224) != 1)
        return IPSEC_HA_Fsm(3u, context_base);

    IPSEC_CTX_LOG_IF_ENABLED(context, 4, 426, " Starting to batch backup the data to slave");

    first_vr = VOS_AVL3_First(context_base + 276, context_base + 300);
    result = IPSEC_VsStartFirstBatchBackup(context_base, first_vr);
    if ((uint32_t)result == 2) {
        RAW_U32((void *)context_base, 1180) = (uint32_t)result;
        return IPSEC_HA_Fsm(3u, context_base);
    }
    return result;
}

