/*
 * Address: 0x1F2E0
 * Symbol: IPSEC_LIB_GetCurrentTime
 * Purpose: Format the current local time string, appending " DST" when daylight saving is active.
 * Security notes: Stack-protector guarded.
 */
int64_t IPSEC_LIB_GetCurrentTime(int64_t out_buf)
{
    STACK_GUARD_INIT();
    int is_dst = 0;
    unsigned int hi = 0;
    unsigned int lo = 0;
    int sec_hi = 0;
    unsigned int sec_lo = 0;
    int ms_rem = 0;
    uint64_t systime = 0;
    int systime_tail = 0;
    uint64_t local_buf[6] = {0, 0, 0, 0, 0, 0};
    uint16_t local_tail = 0;
    unsigned int len;

    VOS_SystimeGet(&systime);
    VOS_SystimeMsSince1970(&systime, &hi, &lo);
    VOS_64Div32(hi, lo, 1000, &sec_hi, &sec_lo, &ms_rem);
    IPSEC_LIB_GetLocalTime(sec_lo, (uint8_t *)local_buf, (uint32_t *)&is_dst);
    if (is_dst != 0) {
        len = (unsigned int)VOS_StrLen((const char *)local_buf);
        if (len - 1 <= 0x30) {
            if ((unsigned int)strncat_s((char *)local_buf + len, 50 - len, " DST", 4) != 0)
                VRP_Assert(IPSEC_LIB_API_C, 928, 0);
        }
    }
    if ((unsigned int)memcpy_s((void *)out_buf, 50, local_buf, 50) != 0)
        VRP_Assert(IPSEC_LIB_API_C, 933, 0);
    RETURN_GUARDED(0);
}

