#include "types.h"

#define IPSEC_LIB_API_C  "/usr1/ipsec/ipsec_v8/src/ipsec/ipsec_lib_api.c"
#define IPSEC_LIB_ESP_C  "/usr1/ipsec/ipsec_v8/src/ipsec/ipsec_lib_esp.c"
#define IPSEC_SSP_COOKIE 3561718379ULL

#define STACK_GUARD_INIT() uintptr_t stack_cookie = _stack_chk_guard
#define STACK_GUARD_CHECK()            \
    do {                              \
        if (stack_cookie != _stack_chk_guard) \
            __stack_chk_fail();       \
    } while (0)
#define RETURN_GUARDED(v)             \
    do {                              \
        STACK_GUARD_CHECK();          \
        return (v);                   \
    } while (0)

#define RAW_U8(base, off)  (*(uint8_t *)((uint8_t *)(base) + (off)))
#define RAW_U16(base, off) (*(uint16_t *)((uint8_t *)(base) + (off)))
#define RAW_U32(base, off) (*(uint32_t *)((uint8_t *)(base) + (off)))
#define RAW_U64(base, off) (*(uint64_t *)((uint8_t *)(base) + (off)))

#define IPSEC_LIB_LOG_WITH_CODE(lib_ctx, code16, line_no, fmt, ...)                              \
    do {                                                                                         \
        IPSEC_MakeDbgLibStrSetter((lib_ctx), 7, (line_no), (fmt), ##__VA_ARGS__);               \
        SSP_Debug(                                                                               \
            RAW_U32((void *)(lib_ctx), 408),                                                     \
            ((uint32_t)(uint16_t)(code16)) | 0x9990000u,                                        \
            RAW_U64((void *)(lib_ctx), 440),                                                     \
            IPSEC_SSP_COOKIE,                                                                    \
            "%s",                                                                               \
            (const char *)((uint8_t *)(lib_ctx) + 448));                                        \
    } while (0)

#define IPSEC_LIB_LOG_IF_ENABLED(lib_ctx, line_no, fmt, ...)                                     \
    do {                                                                                         \
        if (RAW_U8((void *)(lib_ctx), 400) == 1)                                                 \
            IPSEC_LIB_LOG_WITH_CODE((lib_ctx), -27392, (line_no), (fmt), ##__VA_ARGS__);        \
        else if (RAW_U8((void *)(lib_ctx), 403) == 1)                                            \
            IPSEC_LIB_LOG_WITH_CODE((lib_ctx), -28416, (line_no), (fmt), ##__VA_ARGS__);        \
    } while (0)

