/*
 * Address: 0x28448
 * Symbol: IPSECL_PKT_GetAuthHaslen
 * Purpose: Return the authentication tag length for a configured auth algorithm.
 * Security notes: None.
 */
int64_t IPSECL_PKT_GetAuthHaslen(int auth_algo, uint32_t *out_len)
{
    if (auth_algo == 3) {
        *out_len = 16;
        return 16;
    }
    if (auth_algo <= 3) {
        if (auth_algo >= 1) {
            *out_len = 12;
            return 12;
        }
        return VRP_Assert(IPSEC_LIB_PKT_C, 1377, 0);
    }
    if (auth_algo != 4) {
        if (auth_algo == 5) {
            *out_len = 32;
            return 32;
        }
        return VRP_Assert(IPSEC_LIB_PKT_C, 1377, 0);
    }
    *out_len = 24;
    return 24;
}

