#define STACK_GUARD_CHECK()            \
    do {                              \
        if (stack_cookie != _stack_chk_guard) \
            __stack_chk_fail();       \
    } while (0)
#define RETURN_GUARDED(v)             \
    do {                              \
        STACK_GUARD_CHECK();          \
        return (v);                   \
    } while (0)

