int64_t IPSEC_MakeDbgLibStrSetter(int64_t lib_ctx, int comp_id, int line_no, const char *fmt, ...)
{
    STACK_GUARD_INIT();
    char assert_text[100];
    char va_scratch[32];
    char *out_str;
    int prefix_ret;
    unsigned int prefix_len;
    int body_ret;
    va_list ap;

    out_str = (char *)(lib_ctx + 448);
    prefix_ret = snprintf_truncated_s(out_str, 513, "[IPSEC] <%04d%05d>: ", comp_id, line_no);
    if (prefix_ret < 0) {
        memset_s(assert_text, 100, 0);
        snprintf_truncated_s(assert_text, 100, "ret %d", prefix_ret);
        VRP_Assert(IPSEC_MGT_UTIL_C, 2545, assert_text);
        *out_str = 0;
    }

    prefix_len = (unsigned int)VOS_StrLen(out_str);
    memset_s(va_scratch, 32, 0);
    va_start(ap, fmt);
    body_ret = vsnprintf_truncated_s(out_str + prefix_len, 513 - (int)prefix_len, fmt, ap);
    va_end(ap);
    if (body_ret < 0) {
        memset_s(assert_text, 100, 0);
        snprintf_truncated_s(assert_text, 100, "ret %d", body_ret);
        VRP_Assert(IPSEC_MGT_UTIL_C, 2557, assert_text);
        *out_str = 0;
    }
    RETURN_GUARDED(0);
}

