        result = IPSEC_AttachSockForVs((uint32_t *)(sock_state_base + SOCK_OFF_FD), RAW_U32(sock_state, SOCK_OFF_HANDLE), RAW_U32(sock_state, SOCK_OFF_SEQ), 1u, ctx_base);
        RAW_U8(sock_state, SOCK_OFF_FSM_STATE) = next_state;
