/*
 * Address: 0x443C8
 * Symbol: IPSEC_SOCK_CreateSockForVR
 * Purpose: Select the per-VR socket slot, initialize its descriptor, and kick the socket FSM for creation.
 * Security notes: None.
 */
int64_t IPSEC_SOCK_CreateSockForVR(uint32_t *vr_entry, int64_t ctx_base, int protocol, uint16_t sock_version)
{
    uint8_t *sock_state;
    uint8_t debug_enabled;
    uint32_t result32;

    if (ctx_base == 0 || vr_entry == NULL) {
        VRP_Assert(IPSEC_SOCK_MAIN_C, 1171, 0);
        return 1;
    }

    if (sock_version == 1) {
        if (protocol == 50) {
            sock_state = (uint8_t *)vr_entry + 48;
            if ((uint32_t)(RAW_U32(sock_state, SOCK_OFF_FD) + 1) <= 1) {
                memset_s(sock_state, SOCK_SLOT_SIZE, 0);
                RAW_U16(sock_state, SOCK_OFF_SERVICE_ID) = 7196;
                goto initialize_slot;
            }
        } else {
            sock_state = (uint8_t *)vr_entry + 404;
            if ((uint32_t)(RAW_U32(sock_state, SOCK_OFF_FD) + 1) <= 1) {
                memset_s(sock_state, SOCK_SLOT_SIZE, 0);
                RAW_U16(sock_state, SOCK_OFF_SERVICE_ID) = 7196;
                goto initialize_slot;
            }
        }
    } else {
        if (protocol == 50) {
            sock_state = (uint8_t *)vr_entry + 760;
            if ((uint32_t)(RAW_U32(sock_state, SOCK_OFF_FD) + 1) <= 1) {
                memset_s(sock_state, SOCK_SLOT_SIZE, 0);
                RAW_U16(sock_state, SOCK_OFF_SERVICE_ID) = 528;
                goto initialize_slot;
            }
        } else {
            sock_state = (uint8_t *)vr_entry + 1116;
            if ((uint32_t)(RAW_U32(sock_state, SOCK_OFF_FD) + 1) <= 1) {
                memset_s(sock_state, SOCK_SLOT_SIZE, 0);
                RAW_U16(sock_state, SOCK_OFF_SERVICE_ID) = 528;
                goto initialize_slot;
            }
        }
    }

    SOCK_TRACE(
        ctx_base,
        1221,
        "[IPSEC-%s-%x] Socket with FD %d still not closed, but create again. ",
        SOCK_ROLE(ctx_base),
        RAW_U32((void *)ctx_base, 4),
        RAW_U32(sock_state, SOCK_OFF_FD));

initialize_slot:
    RAW_U32(sock_state, SOCK_OFF_VRID) = vr_entry[0];
    RAW_U8(sock_state, 324) = 0;
    RAW_U32(sock_state, SOCK_OFF_PREV_VRID) = vr_entry[0];
    RAW_U32(sock_state, 16) = 0xFFFFFFFFu;
    RAW_U32(sock_state, 280) = 3;
    RAW_U32(sock_state, 276) = (uint32_t)protocol;
    RAW_U64(sock_state, SOCK_OFF_FD) = UINT64_MAX;
    RAW_U8(sock_state, SOCK_OFF_CREATE_PHASE) = 0;
    RAW_U16(sock_state, SOCK_OFF_VERSION) = sock_version;
    RAW_U32(sock_state, SOCK_OFF_ATTACH_FD) = 0xFFFFFFFFu;
    RAW_U32(sock_state, SOCK_OFF_TIMER_ARG) = (uint32_t)protocol;
    RAW_U32(sock_state, SOCK_OFF_ENABLE_FLAG) = 1;

    RAW_U16(sock_state, 0) = (uint16_t)vr_entry[0];
    RAW_U8(sock_state, 2) = (uint8_t)((2 * protocol) | sock_version);
    RAW_U8(sock_state, 3) = RAW_U8((void *)ctx_base, 1128);
    debug_enabled = RAW_U8((void *)ctx_base, 392);
    ++RAW_U8((void *)ctx_base, 1128);

    SOCK_TRACE(
        ctx_base,
        1232,
        "[IPSEC-%s-%x] After socket create handle = %x, VRID = %d, Proto Version = %x, HandleInc = %d",
        SOCK_ROLE(ctx_base),
        RAW_U32((void *)ctx_base, 4),
        RAW_U32(sock_state, SOCK_OFF_HANDLE),
        RAW_U16(sock_state, 0),
        RAW_U8(sock_state, 2),
        RAW_U8(sock_state, 3));

    if (RAW_U32((void *)ctx_base, 364) != 0) {
        SOCK_TRACE(ctx_base, 1256, "[IPSEC] Socket initialization is success");
        return 0;
    }

    result32 = (uint32_t)IPSEC_SOCKI_FSM(0, (int64_t)sock_state, ctx_base);
    if (result32 != 0) {
        memset_s(sock_state, SOCK_SLOT_SIZE, 0);
        if (RAW_U8((void *)ctx_base, 392) == 1) {
            SOCK_TRACE(
                ctx_base,
                1244,
                "[IPSEC-%s-%x] Socket create failed for VRID %d, Protocol %d, Sock Version %d, returned %d",
                SOCK_ROLE(ctx_base),
                RAW_U32((void *)ctx_base, 4),
                vr_entry[0],
                protocol,
                sock_version,
                result32);
        } else {
            if (RAW_U8((void *)ctx_base, 391) != 1)
                return 0;
            SOCK_TRACE(
                ctx_base,
                1244,
                "[IPSEC-%s-%x] Socket create failed for VRID %d, Protocol %d, Sock Version %d, returned %d",
                SOCK_ROLE(ctx_base),
                RAW_U32((void *)ctx_base, 4),
                vr_entry[0],
                protocol,
                sock_version,
                result32);
        }
    }

    if (RAW_U8((void *)ctx_base, 392) == 1) {
        SOCK_TRACE(
            ctx_base,
            1250,
            "[IPSEC-%s-%x] Socket creation is success, Handle = %x",
            SOCK_ROLE(ctx_base),
            RAW_U32((void *)ctx_base, 4),
            RAW_U32(sock_state, SOCK_OFF_HANDLE));
        debug_enabled = RAW_U8((void *)ctx_base, 392);
        if (debug_enabled == 1)
            SOCK_TRACE(ctx_base, 1256, "[IPSEC] Socket initialization is success");
        return 0;
    }

    if (RAW_U8((void *)ctx_base, 391) != 1)
        return 0;

    SOCK_TRACE(
        ctx_base,
        1250,
        "[IPSEC-%s-%x] Socket creation is success, Handle = %x",
        SOCK_ROLE(ctx_base),
        RAW_U32((void *)ctx_base, 4),
        RAW_U32(sock_state, SOCK_OFF_HANDLE));
    SOCK_TRACE(ctx_base, 1256, "[IPSEC] Socket initialization is success");
    return 0;
}


