/*
 * Address: 0x44B78
 * Symbol: IPSEC_SOCK_Init
 * Purpose: Initialize per-VR ESP/AH sockets and apply configured socket options.
 * Security notes: None.
 */
int64_t IPSEC_SOCK_Init(int64_t ctx_base)
{
    uint32_t *vr_entry;
    uint32_t result;
    uint32_t option_result;

    if (ctx_base == 0) {
        VRP_Assert(IPSEC_SOCK_MAIN_C, 1037, 0);
        return 1;
    }

    if (RAW_U8((void *)ctx_base, SOCK_INIT_DONE_OFF) != 0) {
        SOCK_LOG(ctx_base, 1041, "SOCKET initialisation already completed, not required to init again");
        return 0;
    }

    RAW_U8((void *)ctx_base, SOCK_INIT_DONE_OFF) = 1;
    vr_entry = (uint32_t *)VOS_AVL3_First(ctx_base + VR_TREE_ROOT_OFF, ctx_base + VR_TREE_AUX_OFF);
    while (vr_entry != NULL) {
        if (RAW_U8(vr_entry, VR_SOCKET_ENABLE_OFF) == 1) {
            result = IPSEC_SOCK_CreateSockForVR(vr_entry, ctx_base, 50, 1);
            if (result != 0) {
                SOCK_LOG(
                    ctx_base,
                    1056,
                    "[IPSEC-%s-%x] Socket create for VRID %d failed, returned %d",
                    SOCK_ROLE(ctx_base),
                    RAW_U32((void *)ctx_base, 4),
                    vr_entry[0],
                    result);
            } else if (RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF) != 0) {
                vr_entry[96] = RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF);
                vr_entry[97] = RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF + 4);
                option_result = (uint32_t)IPSEC_SOCKI_FSM(5, (int64_t)(vr_entry + 12), ctx_base);
                if (option_result != 0) {
                    SOCK_LOG(
                        ctx_base,
                        1068,
                        "[IPSEC-%s-%x]ESP Sock Set Option failed for VRID %d, returned %d",
                        SOCK_ROLE(ctx_base),
                        RAW_U32((void *)ctx_base, 4),
                        vr_entry[0],
                        option_result);
                }
            }

            result = IPSEC_SOCK_CreateSockForVR(vr_entry, ctx_base, 51, 1);
            if (result != 0) {
                SOCK_LOG(
                    ctx_base,
                    1078,
                    "[IPSEC-%s-%x] Socket create for VRID %d failed, returned %d",
                    SOCK_ROLE(ctx_base),
                    RAW_U32((void *)ctx_base, 4),
                    vr_entry[0],
                    result);
            } else if (RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF) != 0) {
                vr_entry[185] = RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF);
                vr_entry[186] = RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF + 4);
                option_result = (uint32_t)IPSEC_SOCKI_FSM(5, (int64_t)(vr_entry + 101), ctx_base);
                if (option_result != 0) {
                    SOCK_LOG(
                        ctx_base,
                        1090,
                        "[IPSEC-%s-%x] AH socket Set Option failed for VRID %d, returned %d",
                        SOCK_ROLE(ctx_base),
                        RAW_U32((void *)ctx_base, 4),
                        vr_entry[0],
                        option_result);
                }
            }

            result = IPSEC_SOCK_CreateSockForVR(vr_entry, ctx_base, 50, 0);
            if (result != 0) {
                SOCK_LOG(
                    ctx_base,
                    1101,
                    "[IPSEC-%s-%x] Socket create for VRID %d failed, returned %d",
                    SOCK_ROLE(ctx_base),
                    RAW_U32((void *)ctx_base, 4),
                    vr_entry[0],
                    result);
            } else if (RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF) != 0) {
                vr_entry[274] = RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF);
                vr_entry[275] = RAW_U32((void *)ctx_base, CTX_ESP_OPTION_OFF + 4);
                option_result = (uint32_t)IPSEC_SOCKI_FSM(5, (int64_t)(vr_entry + 190), ctx_base);
                if (option_result != 0) {
                    SOCK_LOG(
                        ctx_base,
                        1113,
                        "[IPSEC-%s-%x] ESP socket Set Option failed for VRID %d, returned %d",
                        SOCK_ROLE(ctx_base),
                        RAW_U32((void *)ctx_base, 4),
                        vr_entry[0],
                        option_result);
                }
            }

            result = IPSEC_SOCK_CreateSockForVR(vr_entry, ctx_base, 51, 0);
            if (result != 0) {
                SOCK_LOG(
                    ctx_base,
                    1123,
                    "[IPSEC-%s-%x] Socket create for VRID %d failed, returned %d",
                    SOCK_ROLE(ctx_base),
                    RAW_U32((void *)ctx_base, 4),
                    vr_entry[0],
                    result);
            } else if (RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF) != 0) {
                vr_entry[363] = RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF);
                vr_entry[364] = RAW_U32((void *)ctx_base, CTX_AH_OPTION_OFF + 4);
                option_result = (uint32_t)IPSEC_SOCKI_FSM(5, (int64_t)(vr_entry + 279), ctx_base);
                if (option_result != 0) {
                    SOCK_LOG(
                        ctx_base,
                        1135,
                        "[IPSEC-%s-%x] AH socket Set Option failed for VRID %d, returned %d",
                        SOCK_ROLE(ctx_base),
                        RAW_U32((void *)ctx_base, 4),
                        vr_entry[0],
                        option_result);
                }
            }
        }

        vr_entry = (uint32_t *)VOS_AVL3_Next((int64_t)(vr_entry + 1), ctx_base + VR_TREE_AUX_OFF);
    }

    SOCK_LOG(ctx_base, 1144, "[IPSEC] Socket intialized successfully");
    return 0;
}

/*
 * Address: 0x455A0
 * Symbol: IPSEC_SOCK_CopyDbgTracePacket
 * Purpose: Copy up to 256 KiB of packet data from an mbuf into the debug trace buffer.
 * Security notes: None.
 */
int64_t IPSEC_SOCK_CopyDbgTracePacket(int64_t ctx_base, int64_t trace_ctx_base, int64_t mbuf, unsigned int *out_len, uint64_t *out_buf)
{
    uint32_t total_len;
    int64_t trace_buffer;

    if (ctx_base == 0) {
        VRP_Assert(IPSEC_SOCK_MAIN_C, 1922, 0);
        return 1;
    }
    if (mbuf == 0) {
        VRP_Assert(IPSEC_SOCK_MAIN_C, 1923, 0);
        return 1;
    }

    *out_buf = 0;
    total_len = MBUF_GetTotalDataLength(mbuf);
    trace_buffer = RAW_U64((void *)trace_ctx_base, DBG_TRACE_BUF_PTR_OFF);
    if (trace_buffer == 0)
        return 14;

    if (total_len > 0x40000)
        total_len = 0x40000;

    if ((unsigned int)MBUF_CopyDataFromMBufToBuffer(mbuf, 0, total_len, trace_buffer) != 0) {
        VRP_Assert(IPSEC_SOCK_MAIN_C, 1938, 0);
        return 17;
    }

    *out_len = total_len;
    *out_buf = (uint64_t)trace_buffer;
    return 0;
}

/*
 * Address: 0x456B0
 * Symbol: IPSEC_SOCK_DbgTracePacket
 * Purpose: Submit a copied packet to the protocol packet trace sink.
 * Security notes: Stack-protector guarded.
 */
int64_t IPSEC_SOCK_DbgTracePacket(int64_t ctx_base, int64_t trace_cfg_base, int64_t packet_buf, int64_t trace_info_base, unsigned int packet_len)
{
    STACK_GUARD_INIT();
    IpsecSockTraceRecord trace_record = {0, 0, 0};
    uint32_t trace_handle;

    if (trace_cfg_base != 0 && packet_buf != 0) {
        trace_handle = RAW_U32((void *)trace_cfg_base, DBG_TRACE_TRACE_ID_OFF);
        RAW_U32(&trace_record.word1, 0) = RAW_U32((void *)trace_cfg_base, DBG_TRACE_TOTAL_ID_OFF);
        if (trace_handle != 0) {
            trace_record.word0 = ((uint64_t)packet_len << 32) | RAW_U32((void *)ctx_base, 4);
            RAW_U8(&trace_record.word1, 4) = 6;
            RAW_U8(&trace_record.word1, 5) = RAW_U8((void *)trace_info_base, 0);
            trace_record.word2 = (int32_t)RAW_U32((void *)trace_info_base, 8);
            SSP_ProtocolPacketTrace(trace_handle, &trace_record, RAW_U32((void *)trace_info_base, 4), packet_buf);
        }
    }

    RETURN_GUARDED(0);
}

/*
 * Address: 0x45750
 * Symbol: IPSEC_FindSocket
 * Purpose: Look up a VR entry and return the selected socket-state slot.
 * Security notes: None.
 */
int64_t IPSEC_FindSocket(int64_t ctx_base, int64_t *out_vr_entry, int vrid, int protocol, uint16_t sock_version)
{
    int search_key;
    int64_t vr_entry;

    search_key = vrid;
    vr_entry = VOS_AVL3_Find(ctx_base + VR_TREE_ROOT_OFF, &search_key, ctx_base + VR_TREE_AUX_OFF);
    *out_vr_entry = vr_entry;
    if (vr_entry == 0)
        return 0;

    if (sock_version == 1)
        return protocol == 50 ? vr_entry + SOCK_V1_ESP_OFF : vr_entry + SOCK_V1_AH_OFF;
    return protocol == 50 ? vr_entry + SOCK_V0_ESP_OFF : vr_entry + SOCK_V0_AH_OFF;
}

