int64_t IPSEC_SOCKI_UpdateLDMStatusLC(int64_t ctx_base, int64_t partner_info)
{
    int64_t ldm_node;

    if (RAW_U32((void *)ctx_base, CTX_DEPLOY_TYPE_OFF) != 2)
        return 0;
    if (RAW_U8((void *)ctx_base, 392) == 1 || RAW_U8((void *)ctx_base, 391) == 1)
        CTX_LOG(ctx_base, 3239, "Received Partner status for LDM LC");
    ldm_node = VOS_AVL3_Find(ctx_base + CTX_LDM_TREE_ROOT_OFF, (const void *)partner_info, ctx_base + CTX_LDM_TREE_AUX_OFF);
    if (ldm_node != 0)
        return IPSEC_SOCKI_UpdateLDMStatus(ldm_node, RAW_U32((void *)partner_info, 4), ctx_base);
    return 1;
}

